const clone=v=>structuredClone(v);const id=(p='id')=>`${p}_${globalThis.crypto?.randomUUID?.()??Math.random().toString(36).slice(2)}`;
const getClip=(p,i)=>p.clips?.find(c=>c.id===i);const trackLocked=(p,c)=>p.tracks?.find(t=>t.id===c?.trackId)?.locked;
const editable=(p,c)=>{if(!c)throw new Error('Selection item not found.');if(c.locked||trackLocked(p,c))throw new Error('Selection is locked.');};
export function setSelection(ids=[]){return new Set([...ids].filter(Boolean));}
export function toggleSelection(ids,idValue){const s=new Set(ids||[]);if(s.has(idValue))s.delete(idValue);else if(idValue)s.add(idValue);return s;}
export function groupSelection(project,ids){const p=clone(project),items=ids.map(x=>getClip(p,x)).filter(Boolean);items.forEach(c=>editable(p,c));if(items.length<2)throw new Error('Select at least two objects to group.');const gid=id('group');for(const c of items)c.groupId=gid;return p;}
export function ungroupSelection(project,ids){const p=clone(project),selected=ids.map(x=>getClip(p,x)).filter(Boolean);selected.forEach(c=>editable(p,c));const groups=new Set(selected.map(c=>c.groupId).filter(Boolean));for(const c of p.clips||[])if(groups.has(c.groupId))c.groupId=null;return p;}
export function duplicateSelection(project,ids){const p=clone(project),selected=new Set(ids),copies=[];for(const c of p.clips||[]){if(!selected.has(c.id))continue;editable(p,c);const n=clone(c);n.id=id('clip');n.startUs=(n.startUs||0)+500_000;n.endUs=(n.endUs||0)+500_000;if(n.groupId)n.groupId=id('group');copies.push(n);}p.clips.push(...copies);return p;}
export function reorderSelection(project,ids,mode){const p=clone(project),set=new Set(ids),sel=p.clips.filter(c=>set.has(c.id)),rest=p.clips.filter(c=>!set.has(c.id));sel.forEach(c=>editable(p,c));if(!sel.length)return p;if(mode==='front')p.clips=[...rest,...sel];else if(mode==='back')p.clips=[...sel,...rest];else{for(const c of sel){let i=p.clips.findIndex(x=>x.id===c.id);if(mode==='forward'&&i<p.clips.length-1){[p.clips[i],p.clips[i+1]]=[p.clips[i+1],p.clips[i]];}if(mode==='backward'&&i>0){[p.clips[i],p.clips[i-1]]=[p.clips[i-1],p.clips[i]];}}}return p;}
export function setLocked(project,ids,locked){const p=clone(project);for(const idValue of ids){const c=getClip(p,idValue);if(c)c.locked=!!locked;}return p;}
export function copyStyle(project,idValue){const c=getClip(project,idValue);if(!c)throw new Error('Selection item not found.');return {type:c.type,style:clone(c.content?.style||{}),opacity:c.opacity,blendMode:c.blendMode};}
export function pasteStyle(project,ids,styleClipboard){const p=clone(project);for(const idValue of ids){const c=getClip(p,idValue);editable(p,c);if(!styleClipboard||c.type!==styleClipboard.type)throw new Error('Style is not compatible with this object.');c.content={...(c.content||{}),style:clone(styleClipboard.style||{})};c.opacity=styleClipboard.opacity??c.opacity;c.blendMode=styleClipboard.blendMode||c.blendMode;}return p;}
